package com.acme.core.common.core;

/**
 * Stable error code (generated by engineering-platform 0.1.0).
 * Intentionally minimal: code + message. Framework-neutral, no HTTP transport detail.
 */
public record ErrorCode(String code, String message) {

    public static ErrorCode of(String code, String message) {
        return new ErrorCode(code, message);
    }
}
